mapper.select:
SELECT m.id AS id, m.seq AS seq, m.room_id AS roomId, m.session_id AS sessionId, m.user_id AS userId, u.`name` AS userName, u.avatar_url AS avatarUrl, m.content AS content, m.create_time AS createTime FROM live_message m INNER JOIN `user` u ON u.id = m.user_id WHERE m.session_id = #{sessionId} AND m.status = 1
AND m.seq < #{lastSeq}
ORDER BY m.seq DESC LIMIT #{size}
